{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "df['FLOW_DURATION_MILLISECONDS'] == df['FLOW_END_MILLISECONDS'] - df['FLOW_START_MILLISECONDS']"
      ],
      "features": [
        "FLOW_DURATION_MILLISECONDS",
        "FLOW_END_MILLISECONDS",
        "FLOW_START_MILLISECONDS"
      ],
      "rationale": "Flow duration is defined as the difference between end and start timestamps."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "df['TCP_FLAGS'] == (df['CLIENT_TCP_FLAGS'] | df['SERVER_TCP_FLAGS'])"
      ],
      "features": [
        "TCP_FLAGS",
        "CLIENT_TCP_FLAGS",
        "SERVER_TCP_FLAGS"
      ],
      "rationale": "Cumulative TCP flags across the flow equal the bitwise OR of client and server flags."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES'] == df['IN_PKTS'] + df['OUT_PKTS']"
      ],
      "features": [
        "NUM_PKTS_UP_TO_128_BYTES",
        "NUM_PKTS_128_TO_256_BYTES",
        "NUM_PKTS_256_TO_512_BYTES",
        "NUM_PKTS_512_TO_1024_BYTES",
        "NUM_PKTS_1024_TO_1514_BYTES",
        "IN_PKTS",
        "OUT_PKTS"
      ],
      "rationale": "The sum of packets in all size buckets must equal total packets in both directions."
    },
    {
      "id": "R4",
      "category": "math",
      "alternatives": [
        "df['ICMP_TYPE'] // 256 == df['ICMP_IPV4_TYPE']"
      ],
      "features": [
        "ICMP_TYPE",
        "ICMP_IPV4_TYPE"
      ],
      "rationale": "ICMP_TYPE encodes type (high byte) and code (low byte), so integer division by 256 gives the type."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_AVG_THROUGHPUT'] == df['SRC_TO_DST_SECOND_BYTES'] * 8",
        "np.isclose(df['SRC_TO_DST_AVG_THROUGHPUT'], df['SRC_TO_DST_SECOND_BYTES'] * 8, rtol=0.01)"
      ],
      "features": [
        "SRC_TO_DST_AVG_THROUGHPUT",
        "SRC_TO_DST_SECOND_BYTES"
      ],
      "rationale": "Throughput in bits per second equals bytes per second times 8; integer arithmetic may truncate, so tolerance alternative provided."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_AVG_THROUGHPUT'] == df['DST_TO_SRC_SECOND_BYTES'] * 8",
        "np.isclose(df['DST_TO_SRC_AVG_THROUGHPUT'], df['DST_TO_SRC_SECOND_BYTES'] * 8, rtol=0.01)"
      ],
      "features": [
        "DST_TO_SRC_AVG_THROUGHPUT",
        "DST_TO_SRC_SECOND_BYTES"
      ],
      "rationale": "Throughput in bits per second equals bytes per second times 8; integer arithmetic may truncate, so tolerance alternative provided."
    },
    {
      "id": "R7",
      "category": "math",
      "alternatives": [
        "(df['SRC_TO_DST_IAT_MIN'] <= df['SRC_TO_DST_IAT_AVG']) & (df['SRC_TO_DST_IAT_AVG'] <= df['SRC_TO_DST_IAT_MAX'])"
      ],
      "features": [
        "SRC_TO_DST_IAT_MIN",
        "SRC_TO_DST_IAT_AVG",
        "SRC_TO_DST_IAT_MAX"
      ],
      "rationale": "The average inter-arrival time must lie between the minimum and maximum."
    },
    {
      "id": "R8",
      "category": "math",
      "alternatives": [
        "(df['DST_TO_SRC_IAT_MIN'] <= df['DST_TO_SRC_IAT_AVG']) & (df['DST_TO_SRC_IAT_AVG'] <= df['DST_TO_SRC_IAT_MAX'])"
      ],
      "features": [
        "DST_TO_SRC_IAT_MIN",
        "DST_TO_SRC_IAT_AVG",
        "DST_TO_SRC_IAT_MAX"
      ],
      "rationale": "The average inter-arrival time must lie between the minimum and maximum."
    },
    {
      "id": "R9",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_IAT_STDDEV'] <= (df['SRC_TO_DST_IAT_MAX'] - df['SRC_TO_DST_IAT_MIN']) / 2"
      ],
      "features": [
        "SRC_TO_DST_IAT_STDDEV",
        "SRC_TO_DST_IAT_MIN",
        "SRC_TO_DST_IAT_MAX"
      ],
      "rationale": "Standard deviation of bounded values cannot exceed half the range."
    },
    {
      "id": "R10",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_IAT_STDDEV'] <= (df['DST_TO_SRC_IAT_MAX'] - df['DST_TO_SRC_IAT_MIN']) / 2"
      ],
      "features": [
        "DST_TO_SRC_IAT_STDDEV",
        "DST_TO_SRC_IAT_MIN",
        "DST_TO_SRC_IAT_MAX"
      ],
      "rationale": "Standard deviation of bounded values cannot exceed half the range."
    },
    {
      "id": "R11",
      "category": "math",
      "alternatives": [
        "df['LONGEST_FLOW_PKT'] == df['MAX_IP_PKT_LEN']"
      ],
      "features": [
        "LONGEST_FLOW_PKT",
        "MAX_IP_PKT_LEN"
      ],
      "rationale": "Longest flow packet should equal the maximum IP packet length observed."
    },
    {
      "id": "R12",
      "category": "math",
      "alternatives": [
        "df['SHORTEST_FLOW_PKT'] == df['MIN_IP_PKT_LEN']"
      ],
      "features": [
        "SHORTEST_FLOW_PKT",
        "MIN_IP_PKT_LEN"
      ],
      "rationale": "Shortest flow packet should equal the minimum IP packet length observed."
    },
    {
      "id": "R13",
      "category": "math",
      "alternatives": [
        "(df['FLOW_DURATION_MILLISECONDS'] >= df['DURATION_IN']) & (df['FLOW_DURATION_MILLISECONDS'] >= df['DURATION_OUT'])"
      ],
      "features": [
        "FLOW_DURATION_MILLISECONDS",
        "DURATION_IN",
        "DURATION_OUT"
      ],
      "rationale": "Overall flow duration must be at least as long as each directional stream duration."
    }
  ]
}
